window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-10ff2ef090f7d53c"]={"versions": [{"id": "FIG-10ff2ef090f7d53c", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Artefakt- und Metamodell-Strukturdiagramm der AUTOSAR Adaptive Platform (Methodologie). Es visualisiert die Dekomposition und Einbettung des konfigurierbaren Deliverables <code>Execution Manifest</code> in seine manifestierten Beschreibungsanteile gemäß dem AUTOSAR-Metamodell.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt drei Artefakt-/Modellelemente sowie deren strukturelle Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>Execution Manifest</code>: Übergeordnetes Manifest-Artefakt (symbolisiert als Umschlag/Deliverable).\n</li><li><code>Process</code>: Kind-Artefakt bzw. Beschreibungsdokument (symbolisiert als Dateidokument), das genau einmal (<code>1</code>) über eine gerichtete Aggregation/Komposition (<code>«nesting»</code>) im Execution Manifest geschachtelt ist.\n</li><li><code>Mode-dependent...</code> (Mode-dependent startup configs / Mode-dependent configurations): Kind-Artefakt bzw. Beschreibungsdokument (symbolisiert als Dateidokument), das beliebig oft (<code>0..*</code>) über eine gerichtete Aggregation/Komposition (<code>«nesting»</code>) im Execution Manifest enthalten sein kann.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Ablauf- oder Laufzeitsequenzen. Es definiert die hierarchische Verpackungs- und Schachtelungsstruktur (<code>«nesting»</code>) bei der Erstellung des Auslieferungsartefakts (Deliverable) im Rahmen des Adaptive-Methodik-Workflows.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Deliverable <code>Execution Manifest</code> erfordert zwingend genau eine Prozessdefinition (<code>Process</code>, Multiplizität <code>1</code>) und erlaubt optional mehrere modusabhängige Konfigurationen (<code>0..*</code>). Integratoren und Generatoren müssen sicherstellen, dass jedes Execution Manifest exakt einen Prozess instanziiert und modelliert, während modusabhängige Schalt- bzw. Startkonfigurationen flexibel modular eingebettet werden können.</p>"}, {"id": "FIG-cbb0df6829cac7d5", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Artefakt- und Metamodell-Strukturdiagramm der AUTOSAR Adaptive Platform (Methodologie). Es visualisiert die Dekomposition und Einbettung des konfigurierbaren Deliverables <code>Execution Manifest</code> in seine manifestierten Beschreibungsanteile gemäß dem AUTOSAR-Metamodell.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt drei Artefakt-/Modellelemente sowie deren strukturelle Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>Execution Manifest</code>: Übergeordnetes Manifest-Artefakt (symbolisiert als Umschlag/Deliverable).\n</li><li><code>Process</code>: Kind-Artefakt bzw. Beschreibungsdokument (symbolisiert als Dateidokument), das genau einmal (<code>1</code>) über eine gerichtete Aggregation/Komposition (<code>«nesting»</code>) im Execution Manifest geschachtelt ist.\n</li><li><code>Mode-dependent...</code> (Mode-dependent startup configs / Mode-dependent configurations): Kind-Artefakt bzw. Beschreibungsdokument (symbolisiert als Dateidokument), das beliebig oft (<code>0..*</code>) über eine gerichtete Aggregation/Komposition (<code>«nesting»</code>) im Execution Manifest enthalten sein kann.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Ablauf- oder Laufzeitsequenzen. Es definiert die hierarchische Verpackungs- und Schachtelungsstruktur (<code>«nesting»</code>) bei der Erstellung des Auslieferungsartefakts (Deliverable) im Rahmen des Adaptive-Methodik-Workflows.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Deliverable <code>Execution Manifest</code> erfordert zwingend genau eine Prozessdefinition (<code>Process</code>, Multiplizität <code>1</code>) und erlaubt optional mehrere modusabhängige Konfigurationen (<code>0..*</code>). Integratoren und Generatoren müssen sicherstellen, dass jedes Execution Manifest exakt einen Prozess instanziiert und modelliert, während modusabhängige Schalt- bzw. Startkonfigurationen flexibel modular eingebettet werden können.</p>"}, {"id": "FIG-f4c63fa332f42306", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Artefakt- und Metamodell-Strukturdiagramm der AUTOSAR Adaptive Platform (Methodologie). Es visualisiert die Dekomposition und Einbettung des konfigurierbaren Deliverables <code>Execution Manifest</code> in seine manifestierten Beschreibungsanteile gemäß dem AUTOSAR-Metamodell.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt drei Artefakt-/Modellelemente sowie deren strukturelle Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>Execution Manifest</code>: Übergeordnetes Manifest-Artefakt (symbolisiert als Umschlag/Deliverable).\n</li><li><code>Process</code>: Kind-Artefakt bzw. Beschreibungsdokument (symbolisiert als Dateidokument), das genau einmal (<code>1</code>) über eine gerichtete Aggregation/Komposition (<code>«nesting»</code>) im Execution Manifest geschachtelt ist.\n</li><li><code>Mode-dependent...</code> (Mode-dependent startup configs / Mode-dependent configurations): Kind-Artefakt bzw. Beschreibungsdokument (symbolisiert als Dateidokument), das beliebig oft (<code>0..*</code>) über eine gerichtete Aggregation/Komposition (<code>«nesting»</code>) im Execution Manifest enthalten sein kann.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Ablauf- oder Laufzeitsequenzen. Es definiert die hierarchische Verpackungs- und Schachtelungsstruktur (<code>«nesting»</code>) bei der Erstellung des Auslieferungsartefakts (Deliverable) im Rahmen des Adaptive-Methodik-Workflows.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Deliverable <code>Execution Manifest</code> erfordert zwingend genau eine Prozessdefinition (<code>Process</code>, Multiplizität <code>1</code>) und erlaubt optional mehrere modusabhängige Konfigurationen (<code>0..*</code>). Integratoren und Generatoren müssen sicherstellen, dass jedes Execution Manifest exakt einen Prozess instanziiert und modelliert, während modusabhängige Schalt- bzw. Startkonfigurationen flexibel modular eingebettet werden können.</p>"}], "trans": [{"from": "FIG-10ff2ef090f7d53c", "to": "FIG-cbb0df6829cac7d5", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-cbb0df6829cac7d5", "to": "FIG-f4c63fa332f42306", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
